(function () {
    function getProductByUrl(url) {
    // Product URL patterns by subdomain
    const patterns = {
        'app': {
            Contacts: [
                '/contact/',
                '/companies',
                '/lists/'
            ],
            Campaigns: [
                '/campaigns/',
                '/templates/'
            ],
            Deals: [
                '/crm/',
                '/deals/'
            ],
            eCommerce: [
                '/payment/',
                '/loyalty'
            ],
            Phone: [
                '/phone/'
            ]
        },
        'my': {
            Contacts: [
                '/lists/',
                '/pages'
            ],
            Campaigns: [
                '/camp/',
                '/users/settings',
                '/advanced/'
            ]
        },
        'conversations-app': {
            Conversations: [
                '/'
            ]
        },
        'app-smtp': {
            Campaigns: [
                '/'
            ]
        },
        'app-sms': {
            Campaigns: [
                '/'
            ]
        },
        'automation': {
            Campaigns: [
                '/'
            ]
        }
    };
    // Extract subdomain and path
    const urlObj = new URL(url);
    const { hostname } = urlObj;
    const path = urlObj.pathname;
    // Get subdomain by removing TLD and any staging suffix
    const subdomain = hostname.split('.')[0].replace('-staging', '');
    // Get patterns for the current subdomain
    const subdomainPatterns = patterns[subdomain];
    if (!subdomainPatterns) {
        return 'Unknown';
    }
    // Check each product's patterns
    for (const [product, urlPatterns] of Object.entries(subdomainPatterns)){
        if (urlPatterns.some((pattern)=>path.startsWith(pattern))) {
            return product;
        }
    }
    // Default to Unknown for unknown paths
    return 'Unknown';
}

